INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(408000, 0, 4080, 0, 0, 12, 'Isle of Quel''Danas', 'The Isle of Quel''Danas rises from the sea north of Eversong Woods, and on its plateau lies the Sunwell, the fount of power that Dath''Remar Sunstrider''s people kindled with water carried from the Well of Eternity. In the Third War Arthas marched the Scourge across the isle and used the Sunwell to raise Kel''Thuzad, and the defiled well was lost to the elves. In time the island was overrun by forces sworn to Prince Kael''thas, his Dawnblade and Sunblade with demons, naga and the Wretched at their side, all in the service of the Burning Legion. Against them the Aldor and the Scryers of Shattrath set aside their feud and landed as the Shattered Sun Offensive, setting out from their staging area to win back Sun''s Reach piece by piece. The Offensive fights on for the town, while demons and Scourge clash along the Dead Scar and naga hold the Greengill Coast.', 'warcraft.wiki.gg/wiki/Isle_of_Quel''Danas (Sunwell creation with Well of Eternity water, Third War, Kel''Thuzad, Kael''thas and Kil''jaeden, Offensive claims Sun''s Reach, Velen purifies Sunwell, WotLK guards); creature_text 25162 (Bahduum: Kael''thas thought dead, reigniting the Sunwell for Kil''jaeden, Magisters'' Terrace to the east, plateau to the south); quest 11482 description (Aldor and Scryers set differences aside); quest 11539 description (Kael''thas sided with the Burning Legion; Dawnblade his elite); quest 24522 reward text (Sunwell only recently reclaimed with the Shattered Sun Offensive''s help); DB spawns: Warden of the Sunwell 37523 in area 4094; Dawnblade, Darkspine naga, Wretched, Legion and Scourge spawns per zone_areas; game_event 101-115 and WorldState.cpp Sun''s Reach phases (phase 1 is the staging area only); mod-individual-progression: zone 4080, Magisters'' Terrace and the Sunwell closed below state 12 (PROGRESSION_TBC_TIER_4), Sun''s Reach Harbor ejects characters below it'),
(408001, 1, 4080, 1, 0, 12, 'Shattered Sun Staging Area', 'The Shattered Sun Staging Area is where the Offensive musters newcomers before sending them into the fight. Exarch Larethor, a draenei, commands here beside Captain Theris Dawnhearth, a blood elf who directs the effort to win back Sun''s Reach. Drill Sergeant Bahduum greets each new draft with blunt speeches: draenei who once stood with him at Skettis and in Shadowmoon Valley hear that the situation on Azeroth looks grim, and sin''dorei used to Scryer ways are told to pull their weight or get back on the boat. Vindicator Xayann fits the island''s malfunctioning sentries with new crystal cores to turn them into allies, and the quartermaster Eldara Dawnrunner keeps powerful gear for those who have proven themselves.', 'zone_areas: 4085 holds Larethor 24813, Theris 24967, Xayann 24965, Eldara Dawnrunner 25032, Drill Sergeant Bahduum 25162; creature_text 25162 groups 2-3 (Skettis, Shadowmoon Valley, Scryers, pull your weight or get back on the boat); warcraft.wiki.gg/wiki/Exarch_Larethor (draenei); warcraft.wiki.gg/wiki/Captain_Theris_Dawnhearth (blood elf); quest 11524 description; npc_text 12338 (Eldara); warcraft.wiki.gg/wiki/Exarch_Larethor (draenei, Shattered Sun Offensive; no Aldor tie stated)'),
(408002, 1, 4080, 2, 0, 12, 'Sun''s Reach Sanctum', 'The Sun''s Reach Sanctum is the Offensive''s first goal in the town, and the key to the rest: once it is secure, its energy is to open a portal from Shattrath. The Wretched have overrun it, slipping in after they stole the power sources from its protective crystal wards. Winning it back means hunting the Wretched for the mana remnants they carry and feeding them to the wards, while Vindicator Xayann''s new crystal cores turn the island''s malfunctioning sentries into allies for the assault.', 'quest 11496 description (Wretched stole the ward power sources; sanctum energy to open a portal from Shattrath); quest 11524 and 11525 descriptions (sentries helped take the sanctum); quest 11514 description (mana cells maintain the portal); gameobjects 187335 Portal from Shattrath City and 187116 Monument to the Fallen, posarea 4086; zone_areas: Arynna 25057, Inuuro 25061, Darnarian 25133 in 4086; npc_text 12255 (Inuuro); quest 11545 and 11548 descriptions (memorial fund); game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408003, 1, 4080, 3, 0, 12, 'Sun''s Reach Armory', 'The Sun''s Reach Armory is of great tactical importance to the Offensive, and the Burning Legion holds it. Its demons rally around the emissaries of hate, Legion shocktroopers sent to reinforce key positions, whom they fear more than any foe, and while that fear keeps their morale high the building cannot be taken. To the south the Legion''s forces are tied down for now by the Scourge on the Dead Scar, but the Offensive knows that respite will not last.', 'quest 11538 description (Legion holds the armory; emissaries of hate); quest 11532 description (distraction at the Dead Scar so the armory can be taken); broadcast_text 24078 (The Sun''s Reach Armory is ours, demons pushed back to Dawning Square); broadcast_text 24225 (smith behind the armory); zone_areas: Hauthaa 25046, Ilastar 25069, Kaalan 25108, Kayri/Karynna/Olus/Soryn (Exotic Gear Purveyor) in 4088; gameobjects 187111 anvil, 187112 forge; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408004, 1, 4080, 4, 0, 12, 'Sun''s Reach Harbor', 'Sun''s Reach Harbor is the last stronghold the Offensive needs to make the town its own, and it is held by the Dawnblade, among the most elite of Kael''thas''s armies, who hold Dawnstar Village to the west as well. A ship, Silvermoon''s Pride, lies at its docks. On the western docks Ayren Cloudbreaker keeps the Offensive''s dragonhawks, and from the waterfront Archmage Ne''thul keeps his watch on the Sunwell Plateau.', 'quest 11539 description (Dawnblade one of Kael''s most elite forces, stationed at the harbor and Dawnstar Village); broadcast_text 25851 (harbor taken, Sun''s Reach is ours); npc_text 12287 (Valindria: harbor taken, ship a bonus, not yet sea-worthy); quest 11541 description; warcraft.wiki.gg/wiki/Archmage_Ne''thul (on a boat at Sun''s Reach Harbor); quest 11532 description (Ayren in the west part of the harbor); quest 11546 description and broadcast_text 24230 (Mar''nah inside the inn); zone_areas: Valindria 25088 in 4083, Ne''thul 25169, Ayren 25059, K''iru 25174, Mar''nah 24975 in 4087; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing); quest 11520 description (Mar''nah: little to offer until her reagents are stocked)'),
(408005, 1, 4080, 5, 0, 12, 'The Dawnblade Fleet', 'Off the coast of Sun''s Reach ride three Dawnblade warships, the Dawnchaser, the Sin''loren and the Bloodoath, their decks crowded with reservists bound for the harbor. For all their soldiers, the ships are open to attack from the air: a rider who flies low enough can set their sails ablaze with flaming oil, then drop onto the decks while the crews struggle with the fire and can mount little defense.', 'warcraft.wiki.gg/wiki/Dawnblade_(blood_elves) (three destroyers: Sin''loren, Bloodoath, Dawnchaser); quests 11542 and 11543 descriptions and reward text; zone_areas: Dawnblade Reservist 25087 on 4081, 4082, 4084; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408006, 1, 4080, 6, 0, 12, 'Dawnstar Village', 'Dawnstar Village lies west of the Sun''s Reach Armory, a blood elf village that became the stronghold of the Dawnblade on Quel''Danas. Their summoners, blood knights and marksmen fill its lanes, practicing at archery targets and training dummies, their chargers are kept close by, and Wretched prowl the outskirts. At the village''s edge stands the Bloodcrystal, one of the points on the island''s ley lines.', 'quest 11540 description (Dawnstar Village west of the armory; surviving Dawnblade combatants); warcraft.wiki.gg/wiki/Dawnstar_Village (blood elven village occupied by Dawnblade, wretched nearby); zone_areas 4089: Dawnblade Summoner/Blood Knight/Marksman, Archery Target, Practice Dummy, Dawnstar Charger, Wretched; gameobject 187371 Bloodcrystal (posarea 4089); quest 11547 description; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408007, 1, 4080, 7, 0, 12, 'The Dawning Square', 'South of the Sun''s Reach Sanctum, the Dawning Square belongs to the Burning Legion. A fel portal stands in the middle of the square, and demons guard it in force: irespeakers, unleashed hellions and abyssal flamewalkers, rallied by emissaries of hate whom they fear more than any foe. A magistrix the Offensive sent to investigate the portal never returned. The portal is also one of the points on the island''s ley lines.', 'quest 11526 description (fel portal in the middle of Dawning Square, south of here; operative never returned); npc_text 12239 (Seyla: gateway Kael''s armies used to retreat to the Sunwell); quest 11537 and 11538 descriptions (emissaries of hate; Legion fears them); broadcast_text 24078; zone_areas 4090: Irespeaker 24999, Unleashed Hellion 25002, Abyssal Flamewalker 25001; quest 11547 description (Dawning Square portal, just south of the sanctum); warcraft.wiki.gg/wiki/Dawning_Square; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408008, 1, 4080, 8, 0, 12, 'Greengill Coast', 'Greengill Coast, on the eastern shore southeast of Sun''s Reach, was home to a village of Greengill murlocs until the Darkspine naga came. Their sirens now bind the murlocs with controlling orbs and set them to digging iron ore, which the naga lock in chests for shipment to the Legion. On a ley line near the shore, they have raised a shrine to Queen Azshara.', 'quest 11541 description and reward text; quest 11535 description (naga collecting ore in chests for shipment to the Legion); warcraft.wiki.gg/wiki/Greengill_Coast (murloc village, Darkspine naga, shrine to Azshara on a ley line); quest 11547 (naga shrine at Greengill Coast); zone_areas 4091: Greengill Slave 25084, Darkspine Myrmidon 25060, Darkspine Siren 25073, Darkspine Ore Chest 187264; naga spawns along the island''s east side; warcraft.wiki.gg/wiki/Greengill_Coast (sirens make enslaved murlocs dig iron ore)'),
(408009, 1, 4080, 9, 0, 12, 'The Dead Scar of Quel''Danas', 'The Dead Scar does not end at Silvermoon. On the isle it climbs from the southern shore toward the Sunwell Plateau, and its blight still stirs the dead: skeletal ravagers and frenzied ghouls wander it in great numbers. The Burning Legion has claimed the same ground, with wrath enforcers, eredar sorcerers and pit overlords, and the two hosts are locked in a struggle that keeps the demons too busy to fall upon the Offensive, at least for now.', 'quest 11532 description (Scourge at the Dead Scar keep the Legion occupied; it won''t last long); quest 24535 description (Thalorien fell in what is now the Dead Scar; remains near its southern end on this isle); DB spawns: Skeletal Ravager 25028 x218, Frenzied Ghoul 25027, Wrath Enforcer 25030, Eredar Sorcerer 25033, Pit Overlord 25031; Dead Scar spawns run from x 11546 (south) to 12258, toward Halduron at the plateau (x 12559); creature 37552 at 11781,-7068 (posarea 4092); creature_text 37205 group 5 (none of you will reach the sunwell)'),
(408010, 2, 4080, 1, 0, 12, 'Exarch Larethor', 'Exarch Larethor, a draenei, commands the Shattered Sun Staging Area. Every soldier Shattrath can spare reports to him, Aldor sent by Adyen the Lightwarden and Scryers sent by Dathris Sunstriker, and he greets them all with the same plain warning: whatever the old feud between the two orders, neither has the strength to go it alone, so they will work together, though he has a habit of calling the Scryers cryers. He has a worry of his own besides. Tyrith, a blood elf spy he embedded in the Magisters'' Terrace up the rise to the east, has stopped reporting, and the exarch wants him found.', 'warcraft.wiki.gg/wiki/Exarch_Larethor (draenei, Shattered Sun Staging Area); quests 11481 and 11482 description and reward text; quest 11488 description and log text (Tyrith, blood elf spy, terrace up the rise to the east, failed to report); quest 11490 (Tyrith dies); quest 11492 reward text (Tyrith will be missed; his death not in vain); warcraft.wiki.gg/wiki/Exarch_Larethor (draenei, Shattered Sun Offensive; no Aldor tie stated)'),
(408011, 2, 4080, 2, 0, 12, 'Captain Theris Dawnhearth', 'Captain Theris Dawnhearth, a blood elf of the Shattered Sun Offensive, directs the campaign to retake Sun''s Reach from the staging area. He begins with the sanctum, sending fighters after the Wretched to recover the mana remnants they stole from its crystal wards, so that no Wretched stand in the way when the Offensive unleashes its full attack on the Legion and Kael. When Magistrix Seyla vanished while investigating the fel portal at Dawning Square, he sent help after her with a scroll taken from an enemy corpse.', 'warcraft.wiki.gg/wiki/Captain_Theris_Dawnhearth (blood elf; phase 2 and K''iru yells); quests 11496, 11523, 11526 descriptions; broadcast_text 24079 and 25090; npc_text 12259, 12260 (full scale attack on the Legion and Kael); warcraft.wiki.gg/wiki/Captain_Theris_Dawnhearth (yells at phase 2 and at K''iru''s arrival)'),
(408012, 2, 4080, 3, 0, 12, 'Archmage Ne''thul', 'Archmage Ne''thul, a blood elf of the Shattered Sun Offensive, keeps his post aboard a boat on the waterfront at Sun''s Reach Harbor, looking out toward the Sunwell Plateau to the south. While the rest of the Offensive fights for the town, his charge is the plateau itself and the Sunwell upon it, the heart of everything the enemy came to this island for. Champions sent from Shattrath to join that fight are told to seek him out when they reach the isle.', 'warcraft.wiki.gg/wiki/Archmage_Ne''thul (blood elf, Shattered Sun Offensive, on a boat at Sun''s Reach Harbor, reports on breaking the gates); quest 11550 description and reward text; quests 11551-11553 titles (Agamath, Rohendor, Archonisus); broadcast_text 24232, 24234, 25535; npc_text 12309'),
(408013, 2, 4080, 4, 0, 13, 'Thalorien Dawnseeker', 'Thalorien Dawnseeker was a high elf warrior and the bearer of Quel''Delar, a sword given to his people long ago, which he carried against the Amani in the Troll Wars. When the Scourge came for the Sunwell, he stood among its defenders, and he fell on the Isle of Quel''Danas, on the ground now called the Dead Scar, buying time for his soldiers to make their own preparations. His remains still lie near the Scar''s southern end, known to those who find them as those of the last wielder of Quel''Delar.', 'warcraft.wiki.gg/wiki/Thalorien_Dawnseeker (Troll Wars, Sunwell defender, fell to Morlen Coldgrip, remains on the southern tip of the Dead Scar); creature_text 37205 groups 0-5; quest 24535 description (he fell in what is now the Dead Scar, buying time for his men); npc_text 15155 (remains of the last wielder of Quel''Delar); warcraft.wiki.gg/wiki/Quel''Delar (wielded by Thalorien against the trolls and the Scourge); quest 24461 and 24559 reward text (blade remade although Blood-Queen Lana''thel proclaimed it could not); quest 24454 reward text (the blade came to rest in Icecrown); spell_area 70193 in area 4092 for 24535/24563 (Quel''Delar Phase Shift, phase 2048; creature 37552 phaseMask 2048)'),
(408014, 2, 4080, 5, 0, 12, 'Magister Ilastar', 'Magister Ilastar plans the Offensive''s war against the Dawnblade from the Sun''s Reach Armory. To him the Dawnblade are Kael''s lackeys and dogs, and he has promised to teach them a lesson in humility, sending fighters against their summoners, blood knights and marksmen. The harbor they hold matters above all to the Offensive''s plans, and he means to take it from them, for once it falls, he says, the Offensive can deliver the killing blow to Kael''s faltering armies.', 'npc_text 12339, 12340; quests 11539 and 11540 description and reward text; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408015, 2, 4080, 6, 0, 12, 'Smith Hauthaa', 'Smith Hauthaa refuses to wait for supplies that may never arrive. Behind the Sun''s Reach Armory she sets out to build an anvil and forge to arm and armor the Offensive, and she finds her iron among the enemy: the Darkspine naga of Greengill Coast are filling chests with ore bound for the Legion, and taking it hurts them as much as it helps her.', 'quests 11535, 11536 descriptions; quest 11544 description and reward text; npc_text 12285, 12286; broadcast_text 24225; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408016, 2, 4080, 7, 0, 12, 'Astromancer Darnarian', 'Astromancer Darnarian works the translocation magic of the Sun''s Reach Sanctum and feels badly underappreciated for it. Everyone, he complains, wants instant gratification and never thinks of the effort behind even the simplest portal. His remedy is education. He hands visitors a crystal and sends them to attune it to the ley lines of Quel''Danas at three points: the Bloodcrystal near Dawnstar Village, the Legion''s portal in the Dawning Square, and the naga shrine on Greengill Coast. Only after checking their readings does he trust them with a translocator, warning that if a reading is faulty there is no telling where they will end up, and the blame will be theirs.', 'quest 11547 description, log text and reward text; zone_areas: Darnarian 25133 in 4086; gameobjects 187428/187431 Orb of Translocation in 4086; 187371 Bloodcrystal in 4089; gameobject 186982 Ley Lines of Quel''Danas; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408017, 2, 4080, 8, 0, 12, 'Anchorite Ayuri', 'Anchorite Ayuri will not let the dead of Sun''s Reach be forgotten. With the town won and final victory at hand, she gathers donations for a monument to those who gave their lives retaking it, with whatever remains promised to the widows and orphans of the fallen. Her fellow anchorite Kairthos admits the donations have fallen short of her hopes, and quietly invites the wealthiest champions to make up the difference, promising that all who fought here will know of their deeds.', 'quests 11545 and 11548 descriptions and reward text; npc_text 12322, 12323; quest 11549 description and reward text; gameobject 187116 Monument to the Fallen; game_event 101-115 with game_event_creature, game_event_creature_quest, game_event_gameobject (phase timing)'),
(408018, 3, 4080, 1, 0, 12, 'The Call to Quel''Danas', 'In Shattrath, the two rival orders serving the naaru received the same urgent summons. On the Aldor Rise, Adyen the Lightwarden admitted that his forces were spread thin and that a contingent had already gone to Azeroth to investigate events at the Sunwell Plateau, and he sent whomever he could spare to report to Larethor, wishing he could send more. On the Scryer''s Tier, Dathris Sunstriker ordered every able hand back to Azeroth at once, to fight beside the Aldor of all people, for the situation called for the two orders to set their differences aside.', 'quests 11481 and 11482 descriptions and log text; creature_text 25162 groups 10-11, 16-19; mod-individual-progression zone_shattrath.sql (11481 and 11482 hidden until quest 66012, state 12)'),
(408019, 3, 4080, 2, 0, 12, 'The Reclamation of Sun''s Reach', 'The Offensive lacks the numbers to storm Sun''s Reach outright, so it means to take the town one piece at a time. First comes the sanctum. Fighters hunt the Wretched for the mana remnants stolen from its crystal wards and use them to power the wards again, while Vindicator Xayann fits new cores into the island''s malfunctioning sentries and turns them into guards. Once the sanctum is won, its energy is to open a portal from Shattrath, and the armory and the harbor must follow.', 'quests 11496, 11523, 11524, 11525 descriptions; quests 11513, 11514 descriptions (Bash''ir Landing ethereals, mana cells for the portal); quests 11532, 11538 descriptions; broadcast_text 24079, 24078, 25851, 25090; quest 11539 description; quest 11545 description; warcraft.wiki.gg/wiki/Sun''s_Reach (phased reclamation, Monument to the Fallen); game_event 101-115 and game_event_creature_quest (phase-gated starters); quests 11523, 11525 (event 103, phase 2 onward)'),
(408020, 3, 4080, 3, 0, 12, 'Fire from the Sky', 'Sun''s Reach is to be won from the air as much as on the ground. At the harbor, Ayren Cloudbreaker keeps the Offensive''s dragonhawks ready for any rider with orders to fly, and he welcomes the work: in his line of duty one seldom sees much action, and serving this close to the front lines makes a nice change of pace. Whenever the commanders of Sun''s Reach need a blow struck beyond the reach of their soldiers on the ground, it is to Ayren and his mounts that they send their fighters.', 'quests 11532 and 11533 descriptions and reward text; quests 11542 and 11543 descriptions and reward text; npc_text 12252 (Ayren); npc_text 12257, 12258 (Arynna); creature 25059 Ayren Cloudbreaker: no game_event_creature row, present from phase 1; gossip_menu 9062, npc_text 12252'),
(408021, 3, 4080, 4, 0, 12, 'The Missing Magistrix', 'Magistrix Seyla was sent to investigate the fel portal in the middle of the Dawning Square, and she never came back. Captain Theris Dawnhearth had a scroll, taken from an enemy corpse, that he believed would open the way, and he sent help through after her, with orders to find the magistrix and aid her in any way possible. Where the portal led, and whether Seyla still lived, no one at the staging area could say, and the demons crowding the square gave little cause for hope.', 'quest 11526 description, log text and reward text; npc_text 12239 (Seyla); quests 11515 and 11516 descriptions and reward text (Magistrix Seyla at the Throne of Kil''jaeden, QuestSortID 3483 Hellfire Peninsula)'),
(408022, 3, 4080, 5, 0, 13, 'Thalorien''s Blessing', 'Long after Thalorien Dawnseeker fell, his defiled sword Quel''Delar was found and reforged in Northrend by a champion working with the Silver Covenant or the Sunreavers. Warned by the spirit of Uther that the blade could not be trusted while the Lich King''s evil clung to it, the bearer brought it to Quel''Danas to be cleansed in the Sunwell. Ranger-General Halduron Brightwing would not admit a stranger to his people''s most sacred place, so lately reclaimed, on a tale alone, and set a test: seek the blessing of Thalorien''s remains at the southern end of the Dead Scar.', 'quests 24480, 24522, 24562 descriptions and reward text (Uther''s warning, Halduron''s refusal); quests 24535 and 24563 descriptions and reward text; creature_text 37205 groups 0-9 and 37542 groups 0-4; src/server/scripts/EasternKingdoms/zone_isle_of_queldanas.cpp (event: defenders sent away, waves, Morlen Coldgrip, blessing); quest 24553 description (leaders of Silvermoon within); warcraft.wiki.gg/wiki/Quel''Delar (Lana''thel defiled it; Silver Covenant and Sunreavers restore it)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(408000, 1, 0, 12, 'On the plateau to the south, Kael''thas''s servants and their demon allies have set to work to reignite the Sunwell, and they mean its power for the Burning Legion. Every gain the Offensive makes in Sun''s Reach brings it a step closer to the plateau and the fight to stop them.', 'creature_text 25162 groups 4, 16-17 (plateau to the south; reigniting the Sunwell with his demon friends); quest 11481 description (developments at the Sunwell Plateau)'),
(408000, 2, 13, 255, 'In the end the Legion''s designs on the Sunwell failed. Kil''jaeden, master of the Burning Legion, was turned back, and the Sunwell has been cleansed and burns pure once more. Ranger-General Halduron Brightwing''s wardens now guard the plateau, admitting no one without his leave. The rest of the island is far from quiet: the Offensive''s war against the Dawnblade, the demons and the naga goes on.', 'warcraft.wiki.gg/wiki/Isle_of_Quel''Danas (Sunwell restored, WotLK guards); quests 24522 and 24562 descriptions and reward text (Halduron inspecting the guards; the Sunwell only recently reclaimed)'),
(408002, 1, 0, 255, 'The sanctum has been won, and the Offensive has made it the base for its next move. From its halls Battlemage Arynna and Harbinger Inuuro planned the fight against the Legion in the armory, and Astromancer Darnarian took up his post beside them.', 'quest 11525 description (sanctum taken with the sentries'' help); quest 11523 description (wards reactivated; defenses around the other structures); npc_text 12241, 12255 (Inuuro: armory next), 12259; broadcast_text 24079 (sanctum taken); game_event 103 (Arynna 25057, Inuuro 25061, Darnarian 25133 spawn from phase 2)'),
(408002, 2, 0, 255, 'In time the portal from Shattrath opened beside the sanctum, as the Offensive had planned. Keeping it open is another matter: it needs a steady supply of mana cells, hidden by the ethereals of Bash''ir Landing in Outland, which must be seized again and again or the portal will collapse.', 'quest 11514 description (maintain the portal''s energy or it collapses; mana cells hidden by the Bash''ir Landing ethereals); gameobject 187335 Portal from Shattrath City (posarea 4086)'),
(408002, 3, 0, 255, 'Sun''s Reach has been won at last, and the Offensive counts its dead. Beside the sanctum Anchorite Ayuri gathers donations for a Monument to the Fallen, to honor those who gave their lives retaking the town, with whatever is left promised to the widows and orphans they left behind.', 'quest 11545 description (Sun''s Reach taken; memorial fund; widows and orphans); quest 11548 description; gameobject 187116 Monument to the Fallen, posarea 4086; game_event 110 (Ayuri 25112 and Kairthos 25163 spawn at phase 4)'),
(408003, 1, 0, 255, 'With the sanctum secure, Harbinger Inuuro sends fighters to break the demons'' nerve: they slay the emissaries of hate and impale them on Shattered Sun banners for the Legion to see. Meanwhile Battlemage Arynna''s dragonhawk raids on the Dead Scar keep the Legion''s southern forces too busy to come to the armory''s aid.', 'quest 11538 description (emissaries of hate; banner); quest 11532 description (distraction at the Dead Scar so the armory can be taken); npc_text 12255, 12257; game_event 102 and 103 (Inuuro and Arynna from phase 2)'),
(408003, 2, 0, 255, 'The armory has fallen, and the demons have been pushed back to the Dawning Square. Behind it Smith Hauthaa sets up a forge and works toward an anvil to arm the Offensive, Magister Ilastar and Vindicator Kaalan plan the war against the Dawnblade from its grounds, and a group of purveyors sells exotic gear to the Offensive''s champions.', 'broadcast_text 24078 (The Sun''s Reach Armory is ours, demons pushed back to Dawning Square); quest 11533 description (we''ve taken the armory); quest 11542 description (push to capture the harbor next); broadcast_text 24225 (smith behind the armory); npc_text 12285 (anvil not yet complete); zone_areas: Hauthaa 25046, Ilastar 25069, Kaalan 25108, Kayri/Karynna/Olus/Soryn (Exotic Gear Purveyor) in 4088; gameobjects 187111 anvil, 187112 forge; game_event 107 (these NPCs and the forge from phase 3), 109 (anvil)'),
(408004, 1, 0, 255, 'The harbor has fallen and the Dawnblade have been driven out. Silvermoon''s Pride was taken as a prize, though she is not yet seaworthy, and Captain Valindria keeps her post aboard while she harries the naga of Greengill Coast. In the inn the alchemist Mar''nah sets up shop, though there is little she can offer until her supplies are stocked.', 'broadcast_text 25851 (harbor taken, Sun''s Reach is ours); npc_text 12287 (Valindria: harbor taken, ship a bonus, not yet sea-worthy); quests 11540, 11541, 11543 descriptions; npc_text 12238 (Mar''nah: little to offer until supplied); broadcast_text 24230 (Mar''nah inside the inn); game_event 110 (Valindria 25088 and Mar''nah 24975 spawn at phase 4)'),
(408004, 2, 0, 255, 'With her alchemy lab assembled, Mar''nah is open for business, and she has a discovery to share. The bloodberry grows wild across Azeroth and has long been thought a nuisance, but exposed to the Sunwell''s power it takes on special properties, and she distills it into an elixir.', 'quest 11546 description (bloodberry, a nuisance plant made potent by the Sunwell''s power); npc_text 12237 (shop finally open); gameobject 187115 Alchemy Lab, game_event 114; quest 11546 offered only in game_event 114'),
(408005, 1, 0, 255, 'Vindicator Kaalan means to keep the fleet from reinforcing Kael''s forces at the harbor before the Offensive can take it. He sends riders on Ayren Cloudbreaker''s dragonhawks to burn the sails and finish the reservists on deck, reckoning that every burned sail means a long wait before the harbor sees reinforcements.', 'quest 11542 description and reward text'),
(408005, 2, 0, 255, 'Even with the harbor lost to them, the Dawnblade have not given it up. The fleet comes again, this time to take the harbor back, and Kaalan answers it the same way, with flaming oil from the air and blades on the burning decks.', 'quest 11543 description and reward text (Sun''s Reach captured; fleet on its way to take back the harbor)'),
(408006, 1, 0, 255, 'Once the Dawnblade were driven from the harbor, their survivors fell back here. Magister Ilastar is not content to let them go: he wants every last one slain, for in his eyes they sealed their fate when they followed Kael''thas to the isle.', 'quest 11540 description (harbor taken; Dawnstar Village west of here; surviving Dawnblade combatants sealed their fate)'),
(408007, 1, 0, 255, 'Since the Sun''s Reach Armory fell, this is where the Legion has fallen back, and here the Offensive keeps up the pressure, set on defeating and demoralizing the demons until their hold on the square breaks.', 'broadcast_text 24078 (armory ours, demons pushed back to Dawning Square); quest 11533 description (armory taken); quest 11537 description (continue to defeat and demoralize the Legion); game_event 107 (Hauthaa, Ilastar, Kaalan from phase 3)'),
(408007, 2, 0, 255, 'The fel portal leads far from Quel''Danas. It is joined to a gateway at the Throne of Kil''jaeden in Outland, the passage by which Kael''thas''s armies retreated to the Sunwell, and Legion reinforcements bound for the isle still pour through it.', 'quest 11526 description and reward text; npc_text 12239 (Seyla: gateway Kael''s armies used to retreat to the Sunwell); quest 11516 description (reinforcements through the gateway; QuestSortID 3483)'),
(408008, 1, 0, 255, 'Smith Hauthaa wants that ore for her anvil. Raiding the naga''s chests arms the Offensive and robs the Legion in the same stroke, so her fighters relieve the Darkspine of their iron as often as they can.', 'quest 11535 and 11536 descriptions (naga ore in chests for the Legion; relieving them helps in more ways than one); game_event 107 (Hauthaa from phase 3)'),
(408008, 2, 0, 255, 'Once the harbor is won, Captain Valindria takes charge of disrupting the coast. She has the sirens'' orbs smashed among the slaves so the freed murlocs turn on their masters, but only a little each day, lest the naga turn their full attention on Sun''s Reach.', 'npc_text 12287 (harbor taken; instructed to oversee the disruption of the naga); quest 11541 description and reward text; game_event 110 (Valindria from phase 4)'),
(408009, 1, 13, 255, 'At the Scar''s southern end lie the remains of Thalorien Dawnseeker, the last wielder of Quel''Delar. He fell on this ground in defense of the Sunwell, holding the road against the Scourge to buy his soldiers time to make their own preparations.', 'quests 24535 and 24563 descriptions (he fell in what is now the Dead Scar, buying time for his men; remains near its southern end); npc_text 15155; creature 37552 at 11781,-7068 (posarea 4092), phaseMask 2048'),
(408010, 1, 0, 255, 'Help reached Tyrith too late to save him, but not too late to make his death count. When the exarch heard all that had been done in the terrace, he mourned a good man and admitted he had underestimated the one who came back to tell him.', 'quest 11490 description (Tyrith dies); quest 11492 reward text (Tyrith will be missed; his death not in vain; I''ve underestimated you), turned in to Larethor at the staging area'),
(408011, 1, 0, 255, 'With the crystal wards around the sanctum burning again, Theris does not mean to stop there. He wants wards raised around every other building in Sun''s Reach as well, for the Wretched are stubborn and go on stealing power from the crystals, and in his eyes the safety of the whole operation depends on keeping them armed.', 'broadcast_text 24079 (sanctum taken; send word back to Shattrath); quest 11523 description; npc_text 12259; warcraft.wiki.gg/wiki/Captain_Theris_Dawnhearth (phase 2 yell)'),
(408012, 1, 0, 12, 'Three mighty gates, Agamath, Rohendor and Archonisus, bar the way to the Sunwell''s inner chambers, and the Shattered Sun''s mages work to bring them down one by one. Ne''thul warns all who will listen that if Kil''jaeden rises through the Sunwell, the world will be thrown into a war the like of which it has not seen for ten thousand years.', 'npc_text 12309 (his greeting: should Kil''jaeden rise up through the Sunwell); quests 11551-11553 titles (Agamath, Rohendor, Archonisus); warcraft.wiki.gg/wiki/Archmage_Ne''thul (reports on breaking the gates)'),
(408012, 2, 0, 255, 'The news he gives is grim. Despite every effort, Kael''thas''s sinister plans were carried out: the Sunwell was reignited in readiness for the Deceiver''s arrival, and mighty barriers were raised to hold the Offensive back from its inner chambers while Kil''jaeden bore down upon the world with the full force of the Burning Legion.', 'quest 11550 description and reward text'),
(408013, 1, 0, 255, 'His spirit lingers there. Called up by one who bears Quel''Delar, it relives his last stand: Thalorien orders his soldiers back to the Sunwell to prepare its defenses, swears that none of the Scourge will reach the well while he stands, and faces wave after wave of the dead with the death knight Morlen Coldgrip at their head. His sword was found long after in Icecrown, broken and defiled, where the Blood-Queen Lana''thel declared it could never be remade.', 'creature_text 37205 groups 0-6 (withdraw to the Sunwell; none of you will reach the sunwell); creature_text 37542 (Morlen Coldgrip); src/server/scripts/EasternKingdoms/zone_isle_of_queldanas.cpp (event: defenders sent away, waves, Morlen Coldgrip); warcraft.wiki.gg/wiki/Thalorien_Dawnseeker (fell to Morlen Coldgrip); warcraft.wiki.gg/wiki/Quel''Delar (Lana''thel took it to Icecrown)'),
(408014, 1, 0, 255, 'Victory did not soften him. With the Dawnblade driven out of the harbor and Sun''s Reach won, he admitted he was not satisfied, and sent the hunt on to Dawnstar Village after the survivors, who sealed their fate when they followed Kael''thas to the isle. He likes to wonder aloud what the prince feels as his armies fall, despair, helplessness or fear, and hopes it is all of them.', 'quest 11540 description and reward text; npc_text 12340'),
(408015, 1, 0, 255, 'With the anvil finished, the real work begins. She blends the naga ore into a special alloy with metal from corrupted armaments that fel orcs forged at the Ata''mal Terrace in Shadowmoon Valley, a place holy to the draenei. The anchorites have blessed her anvil so that it can cleanse them, and from it she keeps the Offensive''s soldiers in weapons and armor.', 'quest 11536 description (now that we have an anvil); quest 11544 description and reward text (Ata''mal armaments, alloy, anchorites blessed the anvil); npc_text 12286; game_event 109 (anvil subphase; 11536 and 11544 offered only then)'),
(408017, 1, 0, 255, 'The Monument to the Fallen now stands in Sun''s Reach. It is but a small consolation to the families, and Ayuri still collects for the orphans and spouses of the war''s heroes, reminding visitors of the price of every war, even one that is won.', 'quest 11548 description (we''ve built a memorial; collection for orphans and spouses); npc_text 12323 (isn''t the memorial beautiful; the price of all wars, even ones that are won); gameobject 187116 Monument to the Fallen, game_event 112; 11548 offered only in game_event 112'),
(408018, 1, 0, 255, 'On the isle, Drill Sergeant Bahduum laid out the stakes for the new recruits. Prince Kael''thas had overrun Quel''Danas, and on the plateau he and his demon allies were working to reignite the Sunwell and open a rift for Kil''jaeden. If he succeeded, this world would suffer far worse than Outland ever had. Many of them would not be going home, the sergeant warned, but those who kept their wits would have the better chance.', 'creature_text 25162 groups 16-19; quest 11550 description and reward text (Kael''thas''s plans; the Sunwell reignited for the Deceiver; Kil''jaeden''s summoning)'),
(408019, 1, 0, 255, 'The sanctum fell first, and word went back to Shattrath that the Offensive was making its move. Next came the armory, held by the Legion: emissaries of hate were slain and impaled on Shattered Sun banners to break the demons'' nerve, while dragonhawk raids kept the Legion''s southern forces busy on the Dead Scar.', 'quests 11523, 11525 descriptions (sanctum taken); broadcast_text 24079; quests 11532, 11538 descriptions; game_event 102-110 (each trigger is a quest of phase 2 or later)'),
(408019, 2, 0, 255, 'The armory fell in turn, and the Legion was pushed back to the Dawning Square. Last came the harbor, held by the Dawnblade, Kael''s elite: from the armory Magister Ilastar sent fighters against them, while Vindicator Kaalan''s riders kept their reinforcements from ever reaching the docks.', 'broadcast_text 24078 (armory ours, demons pushed back to Dawning Square); quest 11533 description; quests 11539, 11542 descriptions; game_event 106-110 (each trigger is a quest of phase 3 or later)'),
(408019, 3, 0, 255, 'Then the harbor fell. The Dawnblade were driven out, and Sun''s Reach was wholly the Offensive''s, with final victory, its commanders believed, close at hand. The town had been won at a heavy price, and many who fought for it did not live to see the day.', 'broadcast_text 25851 (harbor taken, Sun''s Reach is ours); quests 11540, 11543 descriptions (Sun''s Reach ours in its entirety); quest 11545 description (memorial fund); game_event 110-112 (each trigger is a quest of phase 4)'),
(408020, 1, 0, 255, 'When the Offensive moved on the armory, Battlemage Arynna knew the Legion would turn on them as soon as its forces to the south were free of the Scourge at the Dead Scar. Her answer was to keep it busy: riders flew over the Scar hurling arcane charges at pit overlords, eredar sorcerers and wrath enforcers.', 'quests 11532 and 11533 descriptions and reward text; npc_text 12257 (Arynna)'),
(408020, 2, 0, 255, 'The armory fell in time, and the strikes over the Scar went on. Then Vindicator Kaalan found the riders a new target: a fleet of Dawnblade reservists sailing to reinforce the harbor. He sent them low over the ships with flaming oil to set the sails alight, then had them drop to the decks to finish the reservists.', 'quest 11533 description (armory taken thanks to the air strikes; strikes continue); quest 11542 description and reward text; npc_text 12258 (armory captured)'),
(408020, 3, 0, 255, 'Once the harbor had fallen, a Dawnblade fleet sailed to take it back, and Kaalan sent the riders out again, low over the ships with flaming oil and then down onto the burning decks. Every burned sail, he reckons, means a long wait before the enemy can bring reinforcements again.', 'quest 11543 description and reward text'),
(408021, 1, 0, 255, 'The portal led to the gateway at the Throne of Kil''jaeden in Outland, by which Kael''thas''s armies had retreated to the Sunwell. Seyla was alive and had little time for Theris''s worry: there were much bigger problems there. Kael''s most loyal followers had gorged on demon blood for days, gaining new powers, and Legion reinforcements for Quel''Danas still poured through the gateway. She set out to strip the felbloods of their stolen strength and to blast the gateway itself.', 'quest 11526 reward text; npc_text 12239 (Seyla); quests 11515 and 11516 descriptions and reward text (Magistrix Seyla at the Throne of Kil''jaeden, QuestSortID 3483 Hellfire Peninsula)'),
(408022, 1, 0, 255, 'There the spirit relived his last stand, sending his soldiers back to the Sunwell and calling on the stranger to stand with him against the Scourge, wave after wave, and against the death knight Morlen Coldgrip.', 'creature_text 37205 groups 0-5 and 37542 groups 0-4; src/server/scripts/EasternKingdoms/zone_isle_of_queldanas.cpp (event: defenders sent away, waves, Morlen Coldgrip)'),
(408022, 2, 0, 255, 'When the battle ended, Thalorien saw Quel''Delar, declared that it had chosen a new wielder, and gave his blessing. Halduron had not expected the spirit to recognize the bearer as the sword''s heir, but he deferred to its judgment and opened the way to the Sunwell.', 'creature_text 37205 groups 7-9 (It''s Quel''Delar; the blade has chosen you); quests 24535 and 24563 reward text');
